From bdc0c4a0f18fbb0f54c84f39affde02eb296da73 Mon Sep 17 00:00:00 2001
From: Martin Topholm <mph@hoth.dk>
Date: Tue, 20 Dec 2016 09:02:43 +0100
Subject: [PATCH] ui: fix ncurses errors

Fix NCURSES errors introduced in commit 94f8626 (main: split struct
target into main/module parts).

diff --git a/termio.c b/termio.c
index 8d5e13f..60adf87 100644
--- a/termio.c
+++ b/termio.c
@@ -369,21 +369,17 @@ termio_cleanup(void)
 			fprintf(stdout, "%c[2;32m%*.*s%c[0m",
 			    0x1b, w_width, w_width, t->host, 0x1b);
 		else if (C_flag && t->af == AF_INET)
-			fprintf(stdout, "%c[2;31m%*.*%sc[0m",
+			fprintf(stdout, "%c[2;31m%*.*s%c[0m",
 			    0x1b, w_width, w_width, t->host, 0x1b);
 		else
 			fprintf(stdout, "%*.*s", w_width, w_width, t->host);
 		if (w_width)
 			fputc(' ', stdout);
-		if (t->duplicate != NULL)
-			fprintf(stdout, "(duplicate of %s)", t->duplicate->host);
-		else {
-			for (i=ifirst; i<ilast; i++) {
-				if (i < t->npkts)
-					fputc(t->res[i % NUM], stdout);
-				else
-					fputc(' ', stdout);
-			}
+		for (i=ifirst; i<ilast; i++) {
+			if (i < t->npkts)
+				fputc(t->res[i % NUM], stdout);
+			else
+				fputc(' ', stdout);
 		}
 		fputc('\n', stdout);
 	}
-- 
2.25.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
ui: fix ncurses errors

Fix NCURSES errors introduced in commit 94f8626 (main: split struct
target into main/module parts).

Here is the root cause:
The bug was caused by incorrect formatting of escape sequences in the `fprintf` function calls, which led to improper display of colored text in the user interface. Additionally, the removal of the conditional check for `t->duplicate` resulted in a change in how packet results were displayed, potentially leading to confusion or errors in output when duplicates were present. These issues were introduced after the structural changes made in commit 94f8626, which split the `struct target` into main and module parts, affecting how data was accessed and displayed.

Here is the patch:
  */
 void
 termio_cleanup(void)
 {
 #ifndef NCURSES
 	setvbuf(stdout, NULL, _IONBF, 0);
 	if (scrbuffer)
 		free(scrbuffer);
 	if (isatty(STDIN_FILENO))
 		tcsetattr(STDIN_FILENO, TCSAFLUSH, &oterm); // XXX: TCASOFT? see openssh
 #else /* NCURSES */
 	struct target *t;
 	int col, i;
 	int imax, ifirst, ilast;

 	t = list;
 	if (t == NULL)
 		return;

 	col = getmaxx(stdscr);
 	imax = MIN(t->npkts, col - labelwidth);
 	imax = MIN(imax, NUM);
 	ifirst = (t->npkts > imax ? t->npkts - imax : 0);
 	ilast = t->npkts;

 	endwin();
 	DL_FOREACH(list, t) {
 		if (C_flag && t->af == AF_INET6)
 			fprintf(stdout, "%c[2;32m%*.*s%c[0m",
 			    0x1b, w_width, w_width, t->host, 0x1b);
 		else if (C_flag && t->af == AF_INET)
-			fprintf(stdout, "%c[2;31m%*.*%sc[0m",
+			fprintf(stdout, "%c[2;31m%*.*s%c[0m",
 			    0x1b, w_width, w_width, t->host, 0x1b);
 		else
 			fprintf(stdout, "%*.*s", w_width, w_width, t->host);
 		if (w_width)
 			fputc(' ', stdout);
-		if (t->duplicate != NULL)
-			fprintf(stdout, "(duplicate of %s)", t->duplicate->host);
-		else {
-			for (i=ifirst; i<ilast; i++) {
-				if (i < t->npkts)
-					fputc(t->res[i % NUM], stdout);
-				else
-					fputc(' ', stdout);
-			}
+		for (i=ifirst; i<ilast; i++) {
+			if (i < t->npkts)
+				fputc(t->res[i % NUM], stdout);
+			else
+				fputc(' ', stdout);
 		}
 		fputc('\n', stdout);
 	}
 #endif /* !NCURSES */
 }
